 "id": "vietnam-ga-kho-gung",
 "name": "Gà Kho Gừng",
 "nameAlt": "The same root twice in one pot, once for sweetness and once for the sting",
 "aliases": ["Ga Kho Gung", "Gà Kho Gừng", "Vietnamese Ginger Chicken", "Ginger Braised Chicken", "Caramel Ginger Chicken", "Chicken Kho", "Ga Kho"],
